def buildMatrix(k: int, rowConditions: list[list[int]], colConditions: list[list[int]]) -> list[list[int]]:
    from collections import defaultdict, deque
    def topo_sort(edges):
        adj = defaultdict(list)
        in_deg = [0] * (k + 1)
        for u, v in edges:
            adj[u].append(v)
            in_deg[v] += 1
        q = deque([i for i in range(1, k + 1) if in_deg[i] == 0])
        res = []
        while q:
            u = q.popleft()
            res.append(u)
            for v in adj[u]:
                in_deg[v] -= 1
                if in_deg[v] == 0: q.append(v)
        return res if len(res) == k else []
    row_order = topo_sort(rowConditions)
    col_order = topo_sort(colConditions)
    if not row_order or not col_order: return []
    row_pos = {val: i for i, val in enumerate(row_order)}
    col_pos = {val: i for i, val in enumerate(col_order)}
    mat = [[0] * k for _ in range(k)]
    for num in range(1, k + 1):
        mat[row_pos[num]][col_pos[num]] = num
    return mat

